func getLsResult(dirPath string) string {
	// Check if dirPath is a valid directory
	if _, err := os.Stat(dirPath); os.IsNotExist(err) || os.IsPermission(err) {
		return ""
	}

	cmd := exec.Command("ls", "-l")
	cmd.Dir = dirPath
	output, err := cmd.CombinedOutput()
	if err != nil {
		return ""
